var mode='of';
var tabs=document.getElementById('tabs');
tabs.addEventListener('click',function(e){
  var b=e.target.closest('button');if(!b)return;
  [].forEach.call(tabs.querySelectorAll('button'),function(x){x.classList.remove('active');});
  b.classList.add('active');mode=b.getAttribute('data-m');
  document.getElementById('p-of').style.display=mode==='of'?'':'none';
  document.getElementById('p-is').style.display=mode==='is'?'':'none';
  document.getElementById('p-ch').style.display=mode==='ch'?'':'none';
  calc();WT.resize();
});
function n(id){var v=parseFloat(document.getElementById(id).value);return isNaN(v)?0:v;}
function tidy(x){return Math.round(x*1e6)/1e6;}
function calc(){
  var res,label,note;
  if(mode==='of'){
    var p=n('a1'),b=n('b1');res=tidy(b*p/100);label='Result';
    note=p+'% of '+b+' is '+res+'.';
  } else if(mode==='is'){
    var a=n('a2'),c=n('b2');
    if(c===0){res=0;note='Cannot divide by zero. Enter a second number that is not zero.';}
    else{res=tidy(a/c*100);note=a+' is '+res+'% of '+c+'.';}
    label='Percent';
  } else {
    var f=n('a3'),t=n('b3');
    if(f===0){res=0;note='Cannot work out a change from zero.';}
    else{res=tidy((t-f)/Math.abs(f)*100);note=res>=0?'That is an increase of '+res+'%.':'That is a decrease of '+Math.abs(res)+'%.';}
    label='Change';
  }
  document.getElementById('res').textContent=res+(mode==='of'?'':'%');
  document.getElementById('reslabel').textContent=label;
  document.getElementById('note').textContent=note;
}
document.getElementById('go').addEventListener('click',calc);
['a1','b1','a2','b2','a3','b3'].forEach(function(id){document.getElementById(id).addEventListener('input',calc);});
document.getElementById('copy').addEventListener('click',function(){
  var ok=WT.copy(document.getElementById('res').textContent);
  document.getElementById('note').textContent=ok?'Result copied to clipboard.':'Copy failed, select the number instead.';
});
calc();
